fs.writeFileSync('\''.github/workflows/publish-source-networks.yml'\'',"name: Publish source networks\n# A GITHUB_TOKEN-created release suppresses release events; the main CI completion also resolves its published tag.\non: # zizmor: ignore[dangerous-triggers]\n  release:\n    types: [published]\n  workflow_run:\n    workflows: [\"CI/CD Pipeline\"]\n    types: [completed]\n    branches: [main]\n  pull_request:\n    branches-ignore: ['\''e2e/**'\'']\n    paths:\n      - \".github/workflows/publish-source-networks.yml\"\n      - \"scripts/check-source-networks.mjs\"\n      - \"scripts/verify-source-network-distribution.mjs\"\n      - \"scripts/lib/source-network-packets.mjs\"\n      - \"rust/tests/web/source-network-packets.test.mjs\"\n  workflow_dispatch:\n    inputs:\n      mode:\n        description: Run packet checks without publication\n        type: choice\n        options: [checks]\n        default: checks\n      pull-request:\n        description: Pull request whose checks were dispatched\n        type: string\n        default: '\'''\''\n      publish:\n        description: Attach verified source packets to a published stable release (main only)\n        type: boolean\n        default: false\n      tag:\n        description: Published stable release tag (empty selects the latest)\n        type: string\n        default: '\'''\''\npermissions:\n  contents: read\nconcurrency:\n  group: source-network-package-${{ github.event.pull_request.number || github.ref }}\n  cancel-in-progress: false\njobs:\n  resolve:\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    if: >-\n      github.event_name != '\''workflow_run'\'' ||\n      (github.event.workflow_run.head_branch == '\''main'\'' &&\n       github.event.workflow_run.head_repository.full_name == github.repository &&\n       github.event.workflow_run.conclusion != '\''cancelled'\'' &&\n       github.event.workflow_run.conclusion != '\''skipped'\'')\n    outputs:\n      tag: ${{ steps.release.outputs.tag }}\n      publish: ${{ steps.release.outputs.publish }}\n      build: ${{ steps.release.outputs.build }}\n    steps:\n      - uses: actions/checkout@v7\n        with:\n          persist-credentials: false\n      - uses: actions/setup-node@v7\n        with:\n          node-version: '\''24.x'\''\n      - name: Resolve the published stable tag\n        id: release\n        env:\n          GH_TOKEN: ${{ github.token }}\n          EVENT: ${{ github.event_name }}\n          REPOSITORY: ${{ github.repository }}\n          REFERENCE: ${{ github.ref }}\n          PUBLISH: ${{ inputs.publish }}\n          INPUT_TAG: ${{ inputs.tag }}\n          RELEASE_TAG: ${{ github.event.release.tag_name }}\n          RUN_HEAD: ${{ github.event.workflow_run.head_sha }}\n          RUN_BRANCH: ${{ github.event.workflow_run.head_branch }}\n          RUN_REPOSITORY: ${{ github.event.workflow_run.head_repository.full_name }}\n          RUN_CONCLUSION: ${{ github.event.workflow_run.conclusion }}\n        run: node scripts/resolve-package-release.mjs\n  packets:\n    needs: resolve\n    if: ${{ !cancelled() && needs.resolve.outputs.build == '\''true'\'' }}\n    runs-on: ubuntu-latest\n    timeout-minutes: 15\n    strategy:\n      fail-fast: false\n      matrix:\n        shard: [0, 1, 2, 3, 4, 5, 6, 7]\n    steps:\n      - uses: actions/checkout@v7\n        with:\n          fetch-depth: 0\n          persist-credentials: false\n      - name: Select the resolved published tag\n        if: needs.resolve.outputs.tag != '\'''\''\n        env:\n          PACKAGE_RELEASE_TAG: ${{ needs.resolve.outputs.tag }}\n        run: |\n          set -euo pipefail\n          [[ \"$PACKAGE_RELEASE_TAG\" =~ ^v[0-9]+\\.[0-9]+\\.[0-9]+$ ]] || exit 1\n          git fetch origin \"refs/tags/$PACKAGE_RELEASE_TAG:refs/tags/$PACKAGE_RELEASE_TAG\"\n          git checkout --detach \"refs/tags/$PACKAGE_RELEASE_TAG\"\n      - uses: actions/setup-node@v7\n        with:\n          node-version: '\''24.x'\''\n      - name: Check out the shared pinned serializer\n        uses: actions/checkout@v7\n        with:\n          repository: link-foundation/meta-language\n          ref: eb0574d5528babd3b4aadece81590d8e2230b99b\n          path: .meta-language\n          persist-credentials: false\n      - name: Install serializer runtime dependencies\n        run: npm ci --prefix .meta-language/js --omit=dev --ignore-scripts --no-audit --no-fund\n      - name: Produce complete lossless packets from the selected source commit\n        env:\n          SOURCE_SHARD: ${{ matrix.shard }}\n          PACKET_DIRECTORY: ${{ runner.temp }}/source-networks\n          TEST_BUDGET_SECONDS: 600\n          TEST_WARN_RATIO_PERCENT: 75\n        run: |\n          bash scripts/run-with-budget.sh source-networks-release \\\n            node scripts/check-source-networks.mjs --meta-language .meta-language \\\n            --shard-count 8 --shard-index \"$SOURCE_SHARD\" --write --output \"$PACKET_DIRECTORY\"\n      - name: Bundle the complete shard with its receipts\n        env:\n          SOURCE_SHARD: ${{ matrix.shard }}\n          PACKET_DIRECTORY: ${{ runner.temp }}/source-networks\n          ARCHIVE_DIRECTORY: ${{ runner.temp }}\n        run: tar -czf \"$ARCHIVE_DIRECTORY/formal-ai-source-networks-$SOURCE_SHARD.tar.gz\" -C \"$PACKET_DIRECTORY\" .\n      - uses: actions/upload-artifact@v7\n        with:\n          name: formal-ai-source-networks-${{ matrix.shard }}\n          path: ${{ runner.temp }}/formal-ai-source-networks-${{ matrix.shard }}.tar.gz\n          if-no-files-found: error\n  attach:\n    needs: [resolve, packets]\n    if: ${{ !cancelled() && needs.resolve.outputs.publish == '\''true'\'' && needs.packets.result == '\''success'\'' }}\n    runs-on: ubuntu-latest\n    timeout-minutes: 15\n    permissions:\n      contents: write\n    steps:\n      - uses: actions/checkout@v7\n        with:\n          fetch-depth: 0\n          persist-credentials: false\n      - name: Select the resolved published tag\n        env:\n          PACKAGE_RELEASE_TAG: ${{ needs.resolve.outputs.tag }}\n        run: |\n          set -euo pipefail\n          [[ \"$PACKAGE_RELEASE_TAG\" =~ ^v[0-9]+\\.[0-9]+\\.[0-9]+$ ]] || exit 1\n          git fetch origin \"refs/tags/$PACKAGE_RELEASE_TAG:refs/tags/$PACKAGE_RELEASE_TAG\"\n          git checkout --detach \"refs/tags/$PACKAGE_RELEASE_TAG\"\n      - uses: actions/setup-node@v7\n        with:\n          node-version: '\''24.x'\''\n      - uses: actions/download-artifact@v8\n        with:\n          pattern: formal-ai-source-networks-*\n          path: ${{ runner.temp }}/source-network-archives\n          merge-multiple: true\n      - name: Verify every shard against the published source commit\n        env:\n          ARCHIVE_DIRECTORY: ${{ runner.temp }}/source-network-archives\n          DISTRIBUTION_DIRECTORY: ${{ runner.temp }}/source-network-distribution\n        run: |\n          set -euo pipefail\n          for shard in 0 1 2 3 4 5 6 7; do\n            mkdir -p \"$DISTRIBUTION_DIRECTORY/shard-$shard\"\n            tar -xzf \"$ARCHIVE_DIRECTORY/formal-ai-source-networks-$shard.tar.gz\" -C \"$DISTRIBUTION_DIRECTORY/shard-$shard\"\n          done\n          node scripts/verify-source-network-distribution.mjs \"$DISTRIBUTION_DIRECTORY\"\n      - name: Attach all verified packets to the stable release\n        env:\n          GH_TOKEN: ${{ github.token }}\n          PACKAGE_RELEASE_TAG: ${{ needs.resolve.outputs.tag }}\n          ARCHIVE_DIRECTORY: ${{ runner.temp }}/source-network-archives\n        run: gh release upload \"$PACKAGE_RELEASE_TAG\" \"$ARCHIVE_DIRECTORY\"/formal-ai-source-networks-*.tar.gz --clobber\n");
